import json
import re

# Exchange rates from Frankfurter (ECB) for 2025-06-05
eur_cny = 8.2008
eur_usd = 1.1423
eur_try = 44.933
eur_sgd = 1.4676
usd_cny = eur_cny / eur_usd
ey_cny = eur_cny
try_cny = eur_cny / eur_try
sgd_cny = eur_cny / eur_sgd

print(f"USD_to_CNY: {usd_cny}")
print(f"EUR_to_CNY: {ey_cny}")
print(f"TRY_to_CNY: {try_cny}")
print(f"SGD_to_CNY: {sgd_cny}")

def to_cny(v, currency):
    if currency == 'USD': return v * usd_cny
    if currency == 'EUR': return v * ey_cny
    if currency == 'TRY': return v * try_cny
    if currency == 'SGD': return v * sgd_cny
    if currency == 'CNY': return v
    return 0

# Parse CSVs with "Date,Activity,Cost" format - Cost is like "123.45 USD"
def parse_amount_cost_line(line):
    line = line.strip()
    if not line or line.startswith('Date'):
        return None
    parts = line.rsplit(',', 1)
    if len(parts) != 2:
        return None
    amount_str = parts[1].strip()
    m = re.match(r'^([\d.]+)\s*(USD|EUR|TRY|CNY|SGD)$', amount_str, re.IGNORECASE)
    if m:
        return float(m.group(1)), m.group(1).upper()
    return None

def parse_person_csv(filepath):
    totals = {'USD': 0.0, 'EUR': 0.0, 'TRY': 0.0, 'CNY': 0.0, 'SGD': 0.0}
    with open(filepath) as f:
        lines = f.readlines()
    for line in lines:
        r = parse_amount_cost_line(line)
        if r:
            amt, cur = r
            totals[cur] += amt
    return totals

# Parse CSV with header like "item,USD,EUR,TRY,CNY"
def parse_multi_currency_csv(filepath):
    totals = {'USD': 0.0, 'EUR': 0.0, 'TRY': 0.0, 'CNY': 0.0, 'SGD': 0.0}
    with open(filepath) as f:
        lines = f.readlines()
    header = lines[0].strip().split(',')
    for line in lines[1:]:
        line = line.strip()
        if not line:
            continue
        vals = line.split(',')
        for i, v in enumerate(vals):
            if i == 0 or not v.strip():
                continue
            col = header[i].strip().upper().replace(' ', '_')
            # Map column names to currencies
            cur = None
            if col in ('USD', 'AMOUNT_USD', 'AMOUNT_CNY', 'AMOUNT_USD', 'AMOUNT_EUR', 'AMOUNT_TRY'):
                cur = col.split('_')[-1]
            elif col == 'CNY':
                cur = 'CNY'
            elif col == 'TRY':
                cur = 'TRY'
            elif col == 'EUR':
                cur = 'EUR'
            elif col == 'USD':
                cur = 'USD'
            else:
                continue
            try:
                totals[cur] += float(v.strip())
            except:
                pass
    return totals

# Parse CSV with "Category,Amount_CNY,Amount_USD,Amount_EUR,Amount_TRY"
